from pathlib import Path

p=Path('FactionLedgerIQ.user.js')
s=p.read_text()

s=s.replace('// @version      1.4.3','// @version      1.4.4',1)
s=s.replace("const VERSION='1.4.3';","const VERSION='1.4.4';",1)

# Replace receipt wire codec with batch+line-index format while keeping old P1/M1 + base64 decoding.
start=s.index('function encodePayload(p){')
end=s.index('function extractPayload(text){', start)
new_codec=r'''function encodePayload(p){if(p&&p.kind==='PAYMENT'){const claims=(p.claims||[]).map((c,i)=>[b36(Number.isInteger(c.wireIndex)?c.wireIndex:i),b36(c.qty),b36(c.amount)].join(',')).join(';');return['P2',cutPrefix(p.batchId,'PAY-'),cutPrefix(p.sourceReceiptBatchId,'BATCH-'),b36(p.member&&p.member.id),claims].join('|');}if(p&&p.kind==='MOVEMENT'){const moves=p.movements||[],idx=new Map(moves.map((m,i)=>[String(m.movementId||''),i])),ms=moves.map(m=>[(m.type==='DISPLAY_IN'?'D':'A'),b36(Math.floor(new Date(m.timestamp||0).getTime()/1000)),b36(m.itemId),b36(m.qty),m.apiVerified?1:0].join(',')).join(';'),cs=(p.claims||[]).map(c=>[b36(idx.get(String(c.movementId||''))||0),b36(c.qty),b36(c.amount)].join(',')).join(';');return['M2',cutPrefix(p.batchId,'BATCH-'),b36(p.player&&p.player.id),ms,cs].join('|');}return btoa(unescape(encodeURIComponent(JSON.stringify(p)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/g,'');}
function decodePayload(code){code=String(code||'').trim();if(code.startsWith('P2|')){const a=code.split('|'),claims=String(a[4]||'').split(';').filter(Boolean).map(x=>{const r=x.split(',');return{id:'',wireIndex:u36(r[0]),itemId:'',itemName:'',qty:u36(r[1]),paidEach:0,costBasisKnown:false,mvAtPurchase:0,mvEachFrozen:0,amount:u36(r[2]),destination:'FACTION_ARMORY',verification:''};});return{kind:'PAYMENT',version:'1.4.4+',batchId:'PAY-'+(a[1]||''),sourceReceiptBatchId:'BATCH-'+(a[2]||''),generatedAt:'',paidAt:'',factionName:state.settings.factionName||'',member:{name:'',id:String(u36(a[3]))},leadership:{name:'',id:''},verificationMethod:'API_VERIFIED',claims,total:claims.reduce((n,c)=>n+Number(c.amount||0),0)};}if(code.startsWith('M2|')){const a=code.split('|'),batch='BATCH-'+(a[1]||''),moves=String(a[3]||'').split(';').filter(Boolean).map((x,i)=>{const r=x.split(','),type=r[0]==='D'?'DISPLAY_IN':'ARMORY_IN',itemId=String(u36(r[2])),apiVerified=r[4]==='1';return{movementId:'R'+i,type,timestamp:new Date(u36(r[1])*1000).toISOString(),itemId,itemName:itemName(itemId),qty:u36(r[3]),from:'PERSONAL_INVENTORY',to:type==='DISPLAY_IN'?'DISPLAY_CASE':'FACTION_ARMORY',apiVerified,apiLogIds:[],verificationSource:type==='DISPLAY_IN'&&apiVerified?'DISPLAY_SNAPSHOT':'',allocations:[],claimIds:[]};}),verification={};moves.forEach(m=>verification[m.movementId]=m.type==='DISPLAY_IN'&&m.apiVerified?'VERIFIED_DISPLAY':m.apiVerified?'MEMBER_VERIFIED':'UNVERIFIED');const claims=String(a[4]||'').split(';').filter(Boolean).map((x,ci)=>{const r=x.split(','),mi=u36(r[0]),m=moves[mi]||{},qty=u36(r[1]),amount=u36(r[2]),c={id:'RB-'+cutPrefix(batch,'BATCH-')+'-'+ci,wireIndex:ci,movementId:m.movementId||('R'+mi),itemId:m.itemId||'',itemName:m.itemName||'',qty,paidEach:0,costBasisKnown:false,mvAtPurchase:0,mvEachFrozen:qty?Math.round(amount/qty):0,amount,status:'SUBMITTED',destination:m.to||'FACTION_ARMORY',verification:verification[m.movementId]||''};if(m.claimIds)m.claimIds.push(c.id);return c;});return{kind:'MOVEMENT',version:'1.4.4+',batchId:batch,generatedAt:'',player:{name:'',id:String(u36(a[2]))},factionName:state.settings.factionName||'',movements:moves,claims,verification};}if(code.startsWith('P1|')){const a=code.split('|'),claims=String(a[4]||'').split(';').filter(Boolean).map(x=>{const r=x.split(','),id='CLM-'+r[0],itemId=String(u36(r[1])),qty=u36(r[2]),amount=u36(r[3]);return{id,itemId,itemName:itemName(itemId),qty,paidEach:0,costBasisKnown:false,mvAtPurchase:0,mvEachFrozen:qty?Math.round(amount/qty):0,amount,destination:'FACTION_ARMORY',verification:''};});return{kind:'PAYMENT',version:'1.4.3+',batchId:'PAY-'+(a[1]||''),sourceReceiptBatchId:'BATCH-'+(a[2]||''),generatedAt:'',paidAt:'',factionName:state.settings.factionName||'',member:{name:'',id:String(u36(a[3]))},leadership:{name:'',id:''},verificationMethod:'API_VERIFIED',claims,total:claims.reduce((n,c)=>n+Number(c.amount||0),0)};}if(code.startsWith('M1|')){const a=code.split('|'),moves=String(a[4]||'').split(';').filter(Boolean).map((x,i)=>{const r=x.split(','),type=r[0]==='D'?'DISPLAY_IN':'ARMORY_IN',itemId=String(u36(r[2])),apiVerified=r[4]==='1';return{movementId:'R'+i,type,timestamp:new Date(u36(r[1])*1000).toISOString(),itemId,itemName:itemName(itemId),qty:u36(r[3]),from:'PERSONAL_INVENTORY',to:type==='DISPLAY_IN'?'DISPLAY_CASE':'FACTION_ARMORY',apiVerified,apiLogIds:[],verificationSource:type==='DISPLAY_IN'&&apiVerified?'DISPLAY_SNAPSHOT':'',allocations:[],claimIds:[]};}),verification={};moves.forEach(m=>verification[m.movementId]=m.type==='DISPLAY_IN'&&m.apiVerified?'VERIFIED_DISPLAY':m.apiVerified?'MEMBER_VERIFIED':'UNVERIFIED');const claims=String(a[5]||'').split(';').filter(Boolean).map((x,ci)=>{const r=x.split(','),mi=u36(r[1]),m=moves[mi]||{},c={id:'CLM-'+r[0],wireIndex:ci,movementId:m.movementId||('R'+mi),itemId:m.itemId||'',itemName:m.itemName||'',qty:u36(r[2]),paidEach:u36(r[3]),costBasisKnown:r[4]==='1',mvAtPurchase:u36(r[5]),mvEachFrozen:u36(r[6]),amount:u36(r[7]),status:'SUBMITTED',destination:m.to||'FACTION_ARMORY',verification:verification[m.movementId]||''};if(m.claimIds)m.claimIds.push(c.id);return c;});return{kind:'MOVEMENT',version:'1.4.3+',batchId:'BATCH-'+(a[1]||''),generatedAt:'',player:{name:unwireName(a[2]||''),id:String(u36(a[3]))},factionName:state.settings.factionName||'',movements:moves,claims,verification};}return legacyDecodePayload(code);}
'''
s=s[:start]+new_codec+s[end:]

# Compact human-facing group helpers and leadership receipt.
insert_at=s.index('function movementReceipt(p){')
helper=r'''function shortDestination(v){return v==='FACTION_ARMORY'?'Armory':v==='DISPLAY_CASE'?'Display':friendly(v);}
function compactReceiptGroups(claims){const map=new Map();for(const c of claims||[]){const q=Math.max(0,Number(c.qty||0)),amount=Number(c.amount||0),rate=q?Math.round(amount/q):0,key=[c.itemId||c.itemName,c.destination||'FACTION_ARMORY',rate,c.verification||''].join('|');if(!map.has(key))map.set(key,{itemId:c.itemId,itemName:c.itemName,destination:c.destination||'FACTION_ARMORY',rate,qty:0,amount:0,verification:c.verification||''});const g=map.get(key);g.qty+=q;g.amount+=amount;}return Array.from(map.values());}
function receiptVerificationSummary(p){const status=receiptOverallStatus(p);if(status!=='VERIFIED')return status;const vals=(p.movements||[]).filter(m=>['ARMORY_IN','DISPLAY_IN'].includes(m.type)).map(m=>(p.verification||{})[m.movementId]||(m.type==='DISPLAY_IN'&&m.apiVerified?'VERIFIED_DISPLAY':m.apiVerified?'MEMBER_VERIFIED':'UNVERIFIED'));if(vals.length&&vals.every(v=>v==='VERIFIED_ARMORY'))return 'VERIFIED — Faction News API';if(vals.length&&vals.every(v=>v==='VERIFIED_DISPLAY'))return 'VERIFIED — Display Case API';return 'VERIFIED';}
'''
s=s[:insert_at]+helper+s[insert_at:]

start=s.index('function movementReceipt(p){')
end=s.index('async function generateReceipt()', start)
new_move=r'''function movementReceipt(p){const l=['**FACTION LEDGER IQ — LEADERSHIP RECEIPT**',`${p.player.name||'Member'}${p.player.id?' ['+p.player.id+']':''}${p.factionName?' · '+p.factionName:''}`,`Batch: \`${p.batchId}\``,''],groups=compactReceiptGroups(p.claims||[]);if(groups.length){l.push('**REIMBURSEMENT**');for(const g of groups)l.push(`${g.itemName} ×${g.qty.toLocaleString()} @ ${money(g.rate)} = **${money(g.amount)}** → ${shortDestination(g.destination)}`);l.push('');}const zero=zeroDepositGroups(p);if(zero.length){l.push('**$0 FACTION DEPOSIT**');for(const g of zero)l.push(`${g.itemName} ×${g.qty.toLocaleString()} → ${shortDestination(g.destination)}`);l.push('');}const total=(p.claims||[]).reduce((n,c)=>n+Number(c.amount||0),0);l.push(`**TOTAL: ${money(total)}**`,receiptVerificationSummary(p),`||FLIQ:${encodePayload(p)}||`);return l.join('\n');}
'''
s=s[:start]+new_move+s[end:]

# Replace payment receipt with compact Discord version.
start=s.index('function paymentReceipt(p){')
end=s.index('function paymentPayloadFromBatch', start)
new_pay_receipt=r'''function paymentReceipt(p){const l=['**FACTION LEDGER IQ — PAYMENT RECEIPT**',`Member: ${p.member.name||'Member'}${p.member.id?' ['+p.member.id+']':''}${p.factionName?' · '+p.factionName:''}`,`Source: \`${p.sourceReceiptBatchId||'Unknown'}\``,`Payment: \`${p.batchId}\``,p.leadership&&p.leadership.name?`Processed By: ${p.leadership.name}${p.leadership.id?' ['+p.leadership.id+']':''}`:'','', '**PAID**'].filter(Boolean),groups=compactReceiptGroups(p.claims||[]);for(const g of groups)l.push(`${g.itemName} ×${g.qty.toLocaleString()} = **${money(g.amount)}**`);l.push('',`**TOTAL PAID: ${money(p.total)}**`,p.verificationMethod==='API_VERIFIED'?'VERIFIED':'MANUAL APPROVAL',`||FLIQ:${encodePayload(p)}||`);return l.join('\n');}
'''
s=s[:start]+new_pay_receipt+s[end:]

# Ensure imported movement receipts always have stable receipt-local line indexes.
needle="if(p.kind!=='MOVEMENT')throw new Error('Unsupported LedgerIQ receipt');if(!p.batchId||!Array.isArray(p.movements)||!Array.isArray(p.claims))throw new Error('Movement receipt is incomplete');"
replace=needle+"p.claims.forEach((c,i)=>{if(!Number.isInteger(c.wireIndex))c.wireIndex=i;});"
assert needle in s, 'movement import validation anchor missing'
s=s.replace(needle,replace,1)

# Map P2 receipt-local indexes back to the member's actual local reimbursement IDs.
old="for(const x of p.claims){const c=claimById(x.id);if(!c||c.status==='VOID')throw new Error('Claim '+String(x.id||'')+' was not found in this LedgerIQ');"
new="const sourceBatch=p.sourceReceiptBatchId?(state.receiptBatches||[]).find(b=>String(b.id||'')===String(p.sourceReceiptBatchId||'')):null;for(const x of p.claims){let c=null;if(Number.isInteger(x.wireIndex)&&sourceBatch){const localId=(sourceBatch.claimIds||[])[x.wireIndex];c=claimById(localId);if(c){x.id=c.id;x.itemId=c.itemId;x.itemName=c.itemName;x.mvEachFrozen=c.mvEachFrozen;}}else c=claimById(x.id);if(!c||c.status==='VOID')throw new Error('Reimbursement '+String(x.id||('line '+(Number(x.wireIndex)+1)))+' was not found in this LedgerIQ');"
assert old in s, 'payment claim mapping anchor missing'
s=s.replace(old,new,1)

# Preserve the line index in leadership-generated payment payloads.
old="claims:payable.map(r=>({id:r.claim.id,itemId:r.claim.itemId,itemName:r.claim.itemName,qty:r.claim.qty,paidEach:Number(r.claim.paidEach||0),costBasisKnown:r.claim.costBasisKnown===true,mvAtPurchase:Number(r.claim.mvAtPurchase||0),mvEachFrozen:Number(r.claim.mvEachFrozen||0),amount:r.claim.amount,destination:r.claim.destination||'FACTION_ARMORY',verification:r.verification||'',verificationMethod,verificationDetail:r.verification||''}))"
new="claims:payable.map(r=>({id:r.claim.id,wireIndex:Number.isInteger(r.claim.wireIndex)?r.claim.wireIndex:p.claims.indexOf(r.claim),itemId:r.claim.itemId,itemName:r.claim.itemName,qty:r.claim.qty,paidEach:Number(r.claim.paidEach||0),costBasisKnown:r.claim.costBasisKnown===true,mvAtPurchase:Number(r.claim.mvAtPurchase||0),mvEachFrozen:Number(r.claim.mvEachFrozen||0),amount:r.claim.amount,destination:r.claim.destination||'FACTION_ARMORY',verification:r.verification||'',verificationMethod,verificationDetail:r.verification||''}))"
assert old in s, 'payAudit claim payload anchor missing'
s=s.replace(old,new,1)

p.write_text(s)
print('patched to v1.4.4')
